// Cracked Clay - dried mud plates with deep cracks. Parametric (u,v), static.
//
// Like Porous Bone the relief is PAINTED: the plates are a Voronoi field, the
// height is a profile of the distance from the crack, and its slope lights
// one rim and shades the other. The plates curl up slightly at the edges, as
// dried clay does; hairline cracks split the big plates.
// SEAM-FREE: whole numbers of cells per turn and wrapped cell indices, so the
// plates close up across u = 0/1 and v = 0/1 (torus, sphere, tubes). Twisted
// gluing (Klein bottle, Moebius band): set MIRROR_V to 1.0.
// Dock colors: u_col1 = dry clay surface, u_col2 = damp depth of the cracks.

const float CELLS_U  = 9.0;    // plates around u (whole number)    [4 .. 24]
const float CELLS_V  = 7.0;    // plates around v (whole number)    [3 .. 24]
const float CRACK    = 0.07;   // crack half-width (cell units)     [0.03 .. 0.15]
const float CURL     = 0.35;   // raised plate edges                [0 .. 1]
const float RELIEF   = 1.4;    // strength of the painted relief    [0 .. 3]
const float HAIRLINE = 0.6;    // fine cracks inside the plates     [0 .. 1]
const float MOTTLE   = 0.25;   // color variation of the clay       [0 .. 0.5]
const float MIRROR_U = 0.0;    // 1 = fold u
const float MIRROR_V = 0.0;    // 1 = fold v (Klein bottle, Moebius band)

// ---- seam-free toolkit: every grid has a whole number of cells per turn and
// ---- every cell index is wrapped, so the pattern repeats exactly at u, v = 0/1
vec2 seamFold(vec2 q) {
    vec2 tri = 0.5 - abs(fract(q) - 0.5);   // 0 -> 0.5 -> 0: equal at both ends
    return mix(q, tri, vec2(MIRROR_U, MIRROR_V));
}

// random value of cell c, wrapped into the period n (negative indices too):
// the same cell one turn away gets the same value.
// NB: helper functions here return float/vecN only -- the per-mesh renamer of
// the engine recognizes those return types, not ivec2.
float cellHash(ivec2 c, ivec2 n, int salt) {
    ivec2 w = ivec2(mod(vec2(c), vec2(n)));
    uint h = uint(w.x) * 0x8da6b343u + uint(w.y) * 0xd8163841u + uint(salt) * 0xcb1ab31fu;
    h ^= h >> 15; h *= 0x2c1b3c6du;
    h ^= h >> 12; h *= 0x297a2d39u;
    h ^= h >> 15;
    return float(h >> 8) * (1.0 / 16777216.0);
}

vec2 cellHash2(ivec2 c, ivec2 n, int salt) {
    return vec2(cellHash(c, n, salt), cellHash(c, n, salt + 101));
}

// value noise with a period of n cells; uv in turns (0..1 = one turn)
float pnoise(vec2 uv, ivec2 n, int salt) {
    vec2 p = uv * vec2(n);
    ivec2 i = ivec2(floor(p));
    vec2 f = fract(p);
    vec2 w = f * f * (3.0 - 2.0 * f);
    float a = cellHash(i, n, salt);
    float b = cellHash(i + ivec2(1, 0), n, salt);
    float c = cellHash(i + ivec2(0, 1), n, salt);
    float d = cellHash(i + ivec2(1, 1), n, salt);
    return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}

// fractal sum: each octave doubles the cells, so it stays periodic
float pfbm(vec2 uv, ivec2 n, int octaves, int salt) {
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    for (int o = 0; o < 6; o++) {
        if (o >= octaves) break;
        sum += amp * pnoise(uv, n, salt + 17 * o);
        norm += amp;
        amp *= 0.5;
        n *= 2;
    }
    return sum / norm;
}

// Voronoi on a grid of n cells per turn (p in cells). Returns
//   x = distance to the nearest point, y = distance to the nearest border,
//   z = random id of the nearest cell.
// rel = p minus the nearest point; edgeDir = unit vector toward the nearest
// border (the downhill direction of anything that rises from the borders).
vec3 pvoronoi(vec2 p, ivec2 n, float jitter, int salt, out vec2 rel, out vec2 edgeDir) {
    ivec2 ip = ivec2(floor(p));
    vec2 fp = fract(p);
    float best = 1.0e9;
    ivec2 bestCell = ivec2(0);
    vec2 bestPt = vec2(0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        ivec2 g = ivec2(i, j);
        vec2 pt = vec2(g) + 0.5 + jitter * (cellHash2(ip + g, n, salt) - 0.5);
        vec2 dv = pt - fp;
        float dd = dot(dv, dv);
        if (dd < best) { best = dd; bestCell = g; bestPt = pt; }
    }
    float border = 1.0e9;
    edgeDir = vec2(1.0, 0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        if (i == 0 && j == 0) continue;
        ivec2 g = bestCell + ivec2(i, j);
        vec2 pt = vec2(g) + 0.5 + jitter * (cellHash2(ip + g, n, salt) - 0.5);
        vec2 ab = pt - bestPt;
        float lab = length(ab);
        if (lab < 1.0e-5) continue;
        vec2 dir = ab / lab;
        float dist = dot(0.5 * (bestPt + pt) - fp, dir);
        if (dist < border) { border = dist; edgeDir = dir; }
    }
    rel = fp - bestPt;
    return vec3(sqrt(best), border, cellHash(ip + bestCell, n, salt + 7));
}

// plate height as a function of the distance b from the crack
float plateHeight(float b) {
    float rise = smoothstep(0.2 * CRACK, 1.6 * CRACK, b);
    float x = (b - 2.6 * CRACK) / (2.2 * CRACK);
    float lip = CURL * exp(-x * x);
    return rise * (1.0 + lip) - 0.15 * CURL * smoothstep(0.0, 0.5, b);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = seamFold(fragCoord / iResolution.xy);
    ivec2 n = ivec2(int(CELLS_U), int(CELLS_V));

    // irregular crack lines: offset by a periodic noise (keeps the period)
    vec2 warp = vec2(pfbm(uv, n, 3, 11), pfbm(uv, n, 3, 23)) - 0.5;
    vec2 p = uv * vec2(n) + 0.35 * warp;

    vec2 rel, edgeDir;
    vec3 vor = pvoronoi(p, n, 0.85, 3, rel, edgeDir);
    float b = vor.y;

    // painted relief: slope of the height profile along the crack normal
    const float DB = 0.004;
    float slope = (plateHeight(b + DB) - plateHeight(b - DB)) / (2.0 * DB);
    vec3 N = normalize(vec3(edgeDir * slope * RELIEF * 0.12, 1.0));
    vec3 L = normalize(vec3(-0.55, 0.65, 0.75));
    float light = dot(N, L) / L.z;

    // hairline cracks: a finer, sparser Voronoi (3x the cells: same period)
    vec2 rel2, dir2;
    vec3 fine = pvoronoi(p * 3.0 + 1.7 * warp, n * 3, 0.9, 41, rel2, dir2);
    float hair = (1.0 - smoothstep(0.0, 0.05, fine.y)) * step(0.45, fine.z);

    // clay color: mottled per area and per plate
    float mottle = pfbm(uv, n * 2, 4, 57);
    vec3 clay = u_col1 * (1.0 - MOTTLE + 2.0 * MOTTLE * mottle) * (0.92 + 0.16 * vor.z);
    float grain = pnoise(uv, n * 40, 77) - 0.5;
    clay *= 1.0 + 0.12 * grain;

    float inCrack = 1.0 - smoothstep(0.3 * CRACK, CRACK, b);
    float depth = 1.0 - smoothstep(0.0, CRACK, b);
    vec3 crackCol = u_col2 * (0.35 + 0.65 * (1.0 - depth));

    vec3 col = clay * light;
    col *= 1.0 - HAIRLINE * 0.45 * hair * smoothstep(CRACK, 3.0 * CRACK, b);
    col = mix(col, crackCol, inCrack);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
